function validate([n]) {
  if (typeof n !== 'string' || n.length < 1 || n.length > 18) return 'n needs 1 to 18 digits.';
  if (!/^[0-9]+$/.test(n)) return 'n may contain digits only.';
  if (n[0] === '0') return 'n is a positive number without leading zeros.';
  return null;
}

