function nearestPalindromic(n) {
  const length = n.length;
  const value = BigInt(n);
  const candidates = [];
  candidates.push(10n ** BigInt(length - 1) - 1n);
  candidates.push(10n ** BigInt(length) + 1n);
  const half = BigInt(n.slice(0, Math.ceil(length / 2)));
  for (const delta of [-1n, 0n, 1n]) {
    const prefix = String(half + delta);
    const mirror = length % 2 === 0 ? prefix : prefix.slice(0, -1);
    candidates.push(BigInt(prefix + mirror.split('').reverse().join('')));
  }
  let best = -1n;
  let bestGap = -1n;
  for (const candidate of candidates) {
    if (candidate === value) {
      continue;
    }
    const gap = candidate > value ? candidate - value : value - candidate;
    if (best < 0n || gap < bestGap || (gap === bestGap && candidate < best)) {
      best = candidate;
      bestGap = gap;
    }
  }
  return String(best);
}

