function nearestPalindromic(n) {
  // Palindromes of a fixed length grow with their left half, so binary search each length.
  const value = BigInt(n);
  const build = (half, length) => {
    const left = String(half);
    return BigInt(left + left.slice(0, Math.floor(length / 2)).split('').reverse().join(''));
  };
  let below = null, above = null;
  for (let length = 1; length <= n.length + 1; length++) {
    const digits = Math.ceil(length / 2);
    const low = length === 1 ? 0 : 10 ** (digits - 1), high = 10 ** digits - 1;
    let lo = low, hi = high, found = null;
    while (lo <= hi) {
      const mid = Math.floor((lo + hi) / 2);
      if (build(mid, length) < value) { found = mid; lo = mid + 1; } else hi = mid - 1;
    }
    if (found !== null) { const p = build(found, length); if (below === null || p > below) below = p; }
    lo = low; hi = high; found = null;
    while (lo <= hi) {
      const mid = Math.floor((lo + hi) / 2);
      if (build(mid, length) > value) { found = mid; hi = mid - 1; } else lo = mid + 1;
    }
    if (found !== null) { const p = build(found, length); if (above === null || p < above) above = p; }
  }
  if (below !== null && value - below <= above - value) return String(below);
  return String(above);
}

