function generate(rand, size) {
  const digit = () => String(Math.floor(rand() * 10));
  const length = size === 'large' ? 14 + Math.floor(rand() * 5) : 1 + Math.floor(rand() * 8);
  const shape = Math.floor(rand() * 7);
  let s;
  if (shape === 0) s = '9'.repeat(length);
  else if (shape === 1) s = '1' + '0'.repeat(length - 1);
  else if (shape === 2) s = length === 1 ? '1' : '1' + '0'.repeat(length - 2) + '1';
  else if (shape === 3) {
    // a palindrome, so the answer must skip n itself
    const left = String(1 + Math.floor(rand() * 9)) + Array.from({ length: Math.ceil(length / 2) - 1 }, digit).join('');
    s = left + left.slice(0, Math.floor(length / 2)).split('').reverse().join('');
  } else s = String(1 + Math.floor(rand() * 9)) + Array.from({ length: length - 1 }, digit).join('');
  return [s];
}
